using System.Net;
using System.Net.Sockets;
using System.Text.Json;
using PaymentAuthorization.Domain;
using PaymentAuthorization.Infrastructure;

namespace PaymentAuthorization.IntegrationTest.PaymentGateway;

public sealed class HttpPaymentGatewayTests : IDisposable
{
    private readonly HttpListener listener = new();
    private readonly HttpClient client;
    private HttpStatusCode status = HttpStatusCode.OK;
    private string responseBody = "";

    private string? method;
    private string? path;
    private string? contentType;
    private string? requestBody;

    public HttpPaymentGatewayTests()
    {
        var probe = new TcpListener(IPAddress.Loopback, 0);
        probe.Start();
        var port = ((IPEndPoint)probe.LocalEndpoint).Port;
        probe.Stop();

        var prefix = $"http://127.0.0.1:{port}/";
        listener.Prefixes.Add(prefix);
        listener.Start();
        _ = Serve();
        client = new HttpClient { BaseAddress = new Uri(prefix) };
    }

    private async Task Serve()
    {
        while (listener.IsListening)
        {
            HttpListenerContext context;
            try { context = await listener.GetContextAsync(); }
            catch (Exception) { return; }

            method = context.Request.HttpMethod;
            path = context.Request.Url!.AbsolutePath;
            contentType = context.Request.ContentType;
            using (var reader = new StreamReader(context.Request.InputStream))
                requestBody = await reader.ReadToEndAsync();

            context.Response.StatusCode = (int)status;
            context.Response.ContentType = "application/json";
            var bytes = System.Text.Encoding.UTF8.GetBytes(responseBody);
            await context.Response.OutputStream.WriteAsync(bytes);
            context.Response.Close();
        }
    }

    private Task<AuthorizationOutcome> Authorize(Money? amount = null) =>
        new HttpPaymentGateway(client).AuthorizeAsync("ORD-7", amount ?? new Money(12.50m, "eur"), CancellationToken.None);

    [Fact]
    public async Task It_posts_the_reference_amount_and_currency_as_json_to_the_authorizations_endpoint()
    {
        responseBody = """{"status":"approved"}""";

        await Authorize();

        Assert.Equal("POST", method);
        Assert.Equal("/v1/authorizations", path);
        Assert.StartsWith("application/json", contentType);
        using var json = JsonDocument.Parse(requestBody!);
        var root = json.RootElement;
        Assert.Equal(3, root.EnumerateObject().Count());
        Assert.Equal("ORD-7", root.GetProperty("reference").GetString());
        Assert.Equal(12.50m, root.GetProperty("amount").GetDecimal());
        Assert.Equal(JsonValueKind.Number, root.GetProperty("amount").ValueKind);
        Assert.Equal("EUR", root.GetProperty("currency").GetString());
    }

    [Fact]
    public async Task An_approved_status_is_read_as_approved()
    {
        responseBody = """{"status":"approved"}""";
        Assert.Equal(AuthorizationOutcome.Approved, await Authorize());
    }

    [Fact]
    public async Task A_declined_status_is_read_as_declined()
    {
        responseBody = """{"status":"declined"}""";
        Assert.Equal(AuthorizationOutcome.Declined, await Authorize());
    }

    [Fact]
    public async Task Extra_fields_in_the_response_are_ignored()
    {
        responseBody = """{"id":"auth_1","status":"approved","risk":{"score":3}}""";
        Assert.Equal(AuthorizationOutcome.Approved, await Authorize());
    }

    [Theory]
    [InlineData("""{"status":"pending"}""")]
    [InlineData("""{"status":"APPROVED"}""")]
    [InlineData("""{"status":null}""")]
    [InlineData("""{}""")]
    [InlineData("null")]
    public async Task An_answer_that_is_not_exactly_approved_is_never_treated_as_approved(string body)
    {
        responseBody = body;
        Assert.Equal(AuthorizationOutcome.Declined, await Authorize());
    }

    [Fact]
    public async Task A_402_refusal_is_a_decline_even_when_the_body_says_approved()
    {
        status = HttpStatusCode.PaymentRequired;
        responseBody = """{"status":"approved"}""";
        Assert.Equal(AuthorizationOutcome.Declined, await Authorize());
    }

    [Fact]
    public async Task A_402_refusal_with_an_empty_body_is_a_decline()
    {
        status = HttpStatusCode.PaymentRequired;
        responseBody = "";
        Assert.Equal(AuthorizationOutcome.Declined, await Authorize());
    }

    [Theory]
    [InlineData(HttpStatusCode.BadRequest)]
    [InlineData(HttpStatusCode.Unauthorized)]
    [InlineData(HttpStatusCode.NotFound)]
    [InlineData(HttpStatusCode.InternalServerError)]
    [InlineData(HttpStatusCode.ServiceUnavailable)]
    public async Task Other_failure_statuses_surface_as_errors_rather_than_declines(HttpStatusCode failure)
    {
        status = failure;
        responseBody = """{"status":"approved"}""";
        var error = await Assert.ThrowsAsync<HttpRequestException>(Authorize);
        Assert.Equal(failure, error.StatusCode);
    }

    [Fact]
    public async Task A_success_response_that_is_not_json_surfaces_as_an_error()
    {
        responseBody = "<html>oops</html>";
        await Assert.ThrowsAnyAsync<JsonException>(() => Authorize());
    }

    [Fact]
    public async Task A_success_response_with_a_wrongly_typed_status_surfaces_as_an_error()
    {
        responseBody = """{"status":42}""";
        await Assert.ThrowsAnyAsync<JsonException>(() => Authorize());
    }

    public void Dispose()
    {
        listener.Close();
        client.Dispose();
    }
}
